"""Immutable, versioned specifications, validated before model execution."""
from dataclasses import dataclass, field, replace
from collections.abc import Mapping
from types import MappingProxyType
import math
from uncertain.utils import digest, canonical


class ConfigError(ValueError):
    pass


def freeze(value):
    if isinstance(value, Mapping):
        return MappingProxyType({str(k): freeze(v) for k, v in value.items()})
    if isinstance(value, (list, tuple)):
        return tuple(freeze(v) for v in value)
    return value


@dataclass(frozen=True)
class ModelSpec:
    model_id: str
    revision: str

    def __post_init__(self):
        if not self.model_id or not self.revision or self.revision in {"main", "latest"}:
            raise ConfigError("model_id and an immutable revision are required")


@dataclass(frozen=True)
class SamplingSpec:
    model: ModelSpec
    n: int
    seed: int
    generation: Mapping = field(default_factory=dict)
    token_budget: int = 128

    def __post_init__(self):
        if type(self.n) is not int or self.n < 1:
            raise ConfigError("n must be a positive integer")
        if type(self.token_budget) is not int or self.token_budget < 1:
            raise ConfigError("token_budget must be a positive integer")
        if type(self.seed) is not int:
            raise ConfigError("seed must be an integer")
        defaults = dict(do_sample=True, temperature=1.0, top_k=0, top_p=1.0, num_beams=1)
        unknown = set(self.generation) - set(defaults)
        if unknown:
            raise ConfigError(f"Unsupported generation controls: {sorted(unknown)}")
        defaults.update(self.generation)
        if defaults["do_sample"] is not True or defaults["num_beams"] != 1:
            raise ConfigError("The reference sampler requires ancestral sampling, num_beams=1")
        if not math.isfinite(defaults["temperature"]) or defaults["temperature"] <= 0:
            raise ConfigError("temperature must be finite and positive")
        if type(defaults["top_k"]) is not int or defaults["top_k"] < 0:
            raise ConfigError("top_k must be a nonnegative integer")
        if not 0 < defaults["top_p"] <= 1:
            raise ConfigError("top_p must be in (0, 1]")
        object.__setattr__(self, "generation", freeze(defaults))

    @property
    def model_distribution(self):
        g = self.generation
        return g["temperature"] == 1 and g["top_k"] == 0 and g["top_p"] == 1

    def __hash__(self):
        return int(digest(self)[:15], 16)


@dataclass(frozen=True)
class UnitSpec:
    name: str = "token"
    boundary: str = "token:v1"
    pad_symbol: str = "<TERMINAL>"

    def __post_init__(self):
        supported = {"token": "token:v1", "word": "whitespace:v1",
                     "sentence": "punctuation:v1"}
        if self.name not in supported or self.boundary != supported[self.name]:
            raise ConfigError(f"Select an explicit supported boundary detector: {supported}")


@dataclass(frozen=True)
class EncoderSpec:
    name: str = "tokens"
    config: Mapping = field(default_factory=dict)
    version: str = "1"

    def __post_init__(self):
        object.__setattr__(self, "config", freeze(self.config))

    def __hash__(self):
        return int(digest(self)[:15], 16)


@dataclass(frozen=True)
class StatisticSpec:
    name: str = "energy"
    config: Mapping = field(default_factory=dict)
    version: str = "1"

    def __post_init__(self):
        object.__setattr__(self, "config", freeze(self.config))

    def __hash__(self):
        return int(digest(self)[:15], 16)


@dataclass(frozen=True)
class EstimatorSpec:
    method: str = "mc"
    zero_policy: str = "infinite"
    confidence: float = .95
    bootstrap: int = 199
    correct_bias: bool = False

    def __post_init__(self):
        if self.method not in {"mc", "exact", "auto"}:
            raise ConfigError("method must be mc, exact, or auto")
        if self.zero_policy != "infinite":
            raise ConfigError("Only explicit infinite zero-hit policy is supported")
        if not 0 < self.confidence < 1:
            raise ConfigError("confidence must be in (0,1)")
        if type(self.bootstrap) is not int or self.bootstrap < 20:
            raise ConfigError("bootstrap must be an integer >=20")


@dataclass(frozen=True)
class MeasureSpec:
    sampling: SamplingSpec
    horizon: int
    short_samples: str
    unit: UnitSpec = field(default_factory=UnitSpec)
    representation: EncoderSpec = field(default_factory=EncoderSpec)
    distance: str = "prefix_indicator"
    distance_config: Mapping = field(default_factory=dict)
    statistic: StatisticSpec | str = "mean"
    warping: str = "identity"
    estimator: EstimatorSpec = field(default_factory=EstimatorSpec)
    mode: str = "observed"
    probability: str = "model"

    def __post_init__(self):
        if type(self.horizon) is not int or self.horizon < 1:
            raise ConfigError("horizon must be a positive integer")
        if self.short_samples not in {"pad", "drop", "compare_ragged"}:
            raise ConfigError("short_samples must be pad, drop, or compare_ragged")
        if self.mode not in {"observed", "entropy", "anticipatory"}:
            raise ConfigError("mode must be observed, entropy, or anticipatory")
        if self.probability not in {"model", "sampling"}:
            raise ConfigError("probability must be model or sampling")
        if isinstance(self.statistic, str):
            object.__setattr__(self, "statistic", StatisticSpec(self.statistic))
        object.__setattr__(self, "distance_config", freeze(self.distance_config))

    @property
    def spec_hash(self):
        return digest(self)

    def __hash__(self):
        return int(self.spec_hash[:15], 16)

    def replace(self, **changes):
        return replace(self, **changes)

    def to_dict(self):
        return canonical(self)

    @classmethod
    def from_dict(cls, data):
        d = dict(data)
        s = dict(d.pop("sampling"))
        s["model"] = ModelSpec(**s["model"])
        d["sampling"] = SamplingSpec(**s)
        for key, typ in (("unit", UnitSpec), ("representation", EncoderSpec),
                         ("estimator", EstimatorSpec), ("statistic", StatisticSpec)):
            if isinstance(d.get(key), dict):
                d[key] = typ(**d[key])
        return cls(**d)
